BEGIN;

-- 1. Ensure required geospatial & allocation columns and index exist on public.wards
ALTER TABLE public.wards
  ADD COLUMN IF NOT EXISTS boundary_coordinates jsonb,
  ADD COLUMN IF NOT EXISTS area_sq_meters double precision DEFAULT 0,
  ADD COLUMN IF NOT EXISTS assigned_department_id uuid,
  ADD COLUMN IF NOT EXISTS assigned_head_id uuid,
  ADD COLUMN IF NOT EXISTS assigned_supervisor_id uuid;

CREATE INDEX IF NOT EXISTS wards_ward_number_idx
  ON public.wards (ward_number);

-- 2. Allow public (citizen portal) & authenticated read of active wards
--    Admin write policies remain unchanged.
ALTER TABLE public.wards ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Authenticated users can read active wards" ON public.wards;
DROP POLICY IF EXISTS "Public can read active wards" ON public.wards;
DROP POLICY IF EXISTS "Public and authenticated users can read active wards" ON public.wards;

CREATE POLICY "Public and authenticated users can read active wards"
ON public.wards
FOR SELECT
TO anon, authenticated
USING (
  is_active = true
  OR EXISTS (
    SELECT 1
    FROM public.user_profiles
    WHERE id = auth.uid()
      AND (
        is_admin = true
        OR role IN (
          'admin',
          'municipal_administrator',
          'deputy_commissioner',
          'area_officer',
          'platform_owner',
          'super_admin'
        )
      )
  )
);

-- 3. Snapshot existing ward metadata & foreign-key links before resetting public.wards
CREATE TEMP TABLE tmp_ward_meta ON COMMIT DROP AS
SELECT DISTINCT ON (ward_number)
  ward_number,
  city_id,
  zone_id,
  assigned_department_id,
  assigned_head_id,
  assigned_supervisor_id,
  created_by
FROM public.wards
WHERE ward_number BETWEEN 1 AND 33
ORDER BY
  ward_number ASC,
  (
    assigned_department_id IS NOT NULL
    OR assigned_head_id IS NOT NULL
    OR assigned_supervisor_id IS NOT NULL
  ) DESC,
  (boundary_coordinates IS NOT NULL) DESC,
  updated_at DESC NULLS LAST;

CREATE TEMP TABLE tmp_user_ward ON COMMIT DROP AS
SELECT u.id AS user_id, w.ward_number
FROM public.user_profiles u
JOIN public.wards w ON w.id = u.assigned_ward_id;

CREATE TEMP TABLE tmp_directory_ward ON COMMIT DROP AS
SELECT d.id AS contact_id, w.ward_number
FROM public.public_directory_contacts d
JOIN public.wards w ON w.id = d.ward_id;

CREATE TEMP TABLE tmp_notice_ward ON COMMIT DROP AS
SELECT n.id AS notice_id, w.ward_number
FROM public.public_notices n
JOIN public.wards w ON w.id = n.ward_id;

CREATE TEMP TABLE tmp_complaint_ward ON COMMIT DROP AS
SELECT c.id AS complaint_id, w.ward_number, c.area_id
FROM public.complaints c
LEFT JOIN public.wards w ON w.id = c.ward_id
WHERE c.ward_id IS NOT NULL
   OR c.area_id IS NOT NULL;

CREATE TEMP TABLE tmp_areas_backup ON COMMIT DROP AS
SELECT
  a.id,
  w.ward_number,
  a.name,
  a.name_hindi,
  a.description,
  a.center_latitude,
  a.center_longitude,
  a.radius_meters,
  a.pincode,
  a.is_active,
  a.created_at,
  a.updated_at,
  a.created_by
FROM public.areas a
JOIN public.wards w ON w.id = a.ward_id;

-- Drop auto-assign trigger first so clearing complaints.ward_id does not re-populate old ward UUIDs
DROP TRIGGER IF EXISTS complaints_auto_assign_ward ON public.complaints;
DROP TRIGGER IF EXISTS complaints_auto_assign_ward_trg ON public.complaints;

-- 4. Clear all FK references to public.wards(id) & public.areas(id), then delete old rows
UPDATE public.complaints
SET ward_id = NULL,
    area_id = NULL
WHERE ward_id IS NOT NULL
   OR area_id IS NOT NULL;

UPDATE public.user_profiles
SET assigned_ward_id = NULL
WHERE assigned_ward_id IS NOT NULL;

UPDATE public.complaint_routing_events
SET previous_ward_id = NULL,
    new_ward_id = NULL
WHERE previous_ward_id IS NOT NULL
   OR new_ward_id IS NOT NULL;

UPDATE public.public_directory_contacts
SET ward_id = NULL
WHERE ward_id IS NOT NULL;

UPDATE public.public_notices
SET ward_id = NULL
WHERE ward_id IS NOT NULL;

DELETE FROM public.areas;
DELETE FROM public.wards;

