INSERT INTO public.wards (
  city_id,
  zone_id,
  ward_number,
  name,
  name_hindi,
  description,
  center_latitude,
  center_longitude,
  radius_meters,
  pincode,
  is_active,
  created_by,
  boundary_coordinates,
  area_sq_meters,
  assigned_department_id,
  assigned_head_id,
  assigned_supervisor_id
)
SELECT
  m.city_id,
  m.zone_id,
  s.ward_number,
  s.name,
  s.name_hindi,
  s.description,
  s.center_latitude,
  s.center_longitude,
  s.radius_meters,
  s.pincode,
  s.is_active,
  m.created_by,
  s.boundary_coordinates,
  s.area_sq_meters,
  m.assigned_department_id,
  m.assigned_head_id,
  m.assigned_supervisor_id
FROM src s
LEFT JOIN tmp_ward_meta m
  ON m.ward_number = s.ward_number
ORDER BY s.ward_number ASC, s.name ASC;

-- 6. Restore public.areas & non-complaint FK links using canonical ward rows (largest piece per ward_number)
WITH canonical_wards AS (
  SELECT DISTINCT ON (ward_number)
    id,
    ward_number
  FROM public.wards
  ORDER BY ward_number ASC, area_sq_meters DESC NULLS LAST, name ASC
)
INSERT INTO public.areas (
  id,
  ward_id,
  name,
  name_hindi,
  description,
  center_latitude,
  center_longitude,
  radius_meters,
  pincode,
  is_active,
  created_at,
  updated_at,
  created_by
)
SELECT
  b.id,
  cw.id,
  b.name,
  b.name_hindi,
  b.description,
  b.center_latitude,
  b.center_longitude,
  b.radius_meters,
  b.pincode,
  b.is_active,
  b.created_at,
  b.updated_at,
  b.created_by
FROM tmp_areas_backup b
JOIN canonical_wards cw
  ON cw.ward_number = b.ward_number;

WITH canonical_wards AS (
  SELECT DISTINCT ON (ward_number)
    id,
    ward_number
  FROM public.wards
  ORDER BY ward_number ASC, area_sq_meters DESC NULLS LAST, name ASC
)
UPDATE public.user_profiles u
SET assigned_ward_id = cw.id
FROM tmp_user_ward t
JOIN canonical_wards cw
  ON cw.ward_number = t.ward_number
WHERE u.id = t.user_id;

WITH canonical_wards AS (
  SELECT DISTINCT ON (ward_number)
    id,
    ward_number
  FROM public.wards
  ORDER BY ward_number ASC, area_sq_meters DESC NULLS LAST, name ASC
)
UPDATE public.public_directory_contacts d
SET ward_id = cw.id
FROM tmp_directory_ward t
JOIN canonical_wards cw
  ON cw.ward_number = t.ward_number
WHERE d.id = t.contact_id;

WITH canonical_wards AS (
  SELECT DISTINCT ON (ward_number)
    id,
    ward_number
  FROM public.wards
  ORDER BY ward_number ASC, area_sq_meters DESC NULLS LAST, name ASC
)
UPDATE public.public_notices n
SET ward_id = cw.id
FROM tmp_notice_ward t
JOIN canonical_wards cw
  ON cw.ward_number = t.ward_number
WHERE n.id = t.notice_id;

UPDATE public.complaints c
SET area_id = t.area_id
FROM tmp_complaint_ward t
WHERE c.id = t.complaint_id
  AND t.area_id IS NOT NULL
  AND EXISTS (
    SELECT 1
    FROM public.areas a
    WHERE a.id = t.area_id
  );

-- 7. Pure PL/pgSQL Ray-Casting Point-in-Polygon helpers & auto-assign trigger
CREATE OR REPLACE FUNCTION public.betul_point_in_ring(
  p_lat double precision,
  p_lng double precision,
  p_ring jsonb
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_len integer;
  v_i integer;
  v_j integer;
  v_inside boolean := false;
  v_xi double precision;
  v_yi double precision;
  v_xj double precision;
  v_yj double precision;
BEGIN
  IF p_ring IS NULL OR jsonb_typeof(p_ring) <> 'array' THEN
    RETURN false;
  END IF;

  v_len := jsonb_array_length(p_ring);
  IF v_len < 3 THEN
    RETURN false;
  END IF;

  v_j := v_len - 1;
  FOR v_i IN 0..(v_len - 1) LOOP
    v_xi := (p_ring->v_i->>0)::double precision;
    v_yi := (p_ring->v_i->>1)::double precision;
    v_xj := (p_ring->v_j->>0)::double precision;
    v_yj := (p_ring->v_j->>1)::double precision;

    IF ((v_yi > p_lng) <> (v_yj > p_lng))
       AND (p_lat < ((v_xj - v_xi) * (p_lng - v_yi)) / NULLIF(v_yj - v_yi, 0) + v_xi) THEN
      v_inside := NOT v_inside;
    END IF;

    v_j := v_i;
  END LOOP;

  RETURN v_inside;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION public.betul_point_in_boundary(
  p_lat double precision,
  p_lng double precision,
  p_boundary jsonb
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_elem jsonb;
BEGIN
  IF p_boundary IS NULL OR jsonb_typeof(p_boundary) <> 'array' OR jsonb_array_length(p_boundary) = 0 THEN
    RETURN false;
  END IF;

  -- Multi-polygon: [ [ [lat, lng], ... ], [ [lat, lng], ... ] ]
  IF jsonb_typeof(p_boundary->0->0) = 'array' THEN
    FOR v_elem IN SELECT value FROM jsonb_array_elements(p_boundary) LOOP
      IF public.betul_point_in_ring(p_lat, p_lng, v_elem) THEN
        RETURN true;
      END IF;
    END LOOP;
    RETURN false;
  END IF;

  -- Single polygon: [ [lat, lng], ... ]
  RETURN public.betul_point_in_ring(p_lat, p_lng, p_boundary);
END;
$$;

CREATE OR REPLACE FUNCTION public.betul_find_ward_id(
  p_lat double precision,
  p_lng double precision
)
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_ward_id uuid;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RETURN NULL;
  END IF;

  -- Pass 1: Exact polygon match (prefer tighter boundary if pieces adjoin)
  SELECT id INTO v_ward_id
  FROM public.wards
  WHERE is_active = true
    AND boundary_coordinates IS NOT NULL
    AND public.betul_point_in_boundary(p_lat, p_lng, boundary_coordinates)
  ORDER BY area_sq_meters ASC NULLS LAST, ward_number ASC
  LIMIT 1;

  IF v_ward_id IS NOT NULL THEN
    RETURN v_ward_id;
  END IF;

  -- Pass 2: Haversine fallback only for wards that have a non-null center and positive radius
  SELECT id INTO v_ward_id
  FROM (
    SELECT
      id,
      radius_meters AS r_m,
      6371000.0 * 2.0 * atan2(
        sqrt(
          power(sin(radians(p_lat - center_latitude) / 2.0), 2)
          + cos(radians(center_latitude)) * cos(radians(p_lat))
          * power(sin(radians(p_lng - center_longitude) / 2.0), 2)
        ),
        sqrt(
          GREATEST(
            0.0,
            1.0 - (
              power(sin(radians(p_lat - center_latitude) / 2.0), 2)
              + cos(radians(center_latitude)) * cos(radians(p_lat))
              * power(sin(radians(p_lng - center_longitude) / 2.0), 2)
            )
          )
        )
      ) AS dist_m
    FROM public.wards
    WHERE is_active = true
      AND center_latitude IS NOT NULL
      AND center_longitude IS NOT NULL
      AND radius_meters > 0
  ) ranked
  WHERE ranked.dist_m <= ranked.r_m
  ORDER BY ranked.dist_m ASC
  LIMIT 1;

  RETURN v_ward_id;
END;
$$;

REVOKE ALL ON FUNCTION public.betul_point_in_ring(double precision, double precision, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.betul_point_in_ring(double precision, double precision, jsonb) TO anon, authenticated;

REVOKE ALL ON FUNCTION public.betul_point_in_boundary(double precision, double precision, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.betul_point_in_boundary(double precision, double precision, jsonb) TO anon, authenticated;

REVOKE ALL ON FUNCTION public.betul_find_ward_id(double precision, double precision) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.betul_find_ward_id(double precision, double precision) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.trg_complaints_auto_assign_ward()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.ward_id IS NULL AND NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
    NEW.ward_id := public.betul_find_ward_id(NEW.latitude, NEW.longitude);
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER complaints_auto_assign_ward_trg
  BEFORE INSERT OR UPDATE OF latitude, longitude
  ON public.complaints
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_complaints_auto_assign_ward();

-- 8. Re-link existing complaints: exact GPS boundary match first, then prior ward_number fallback
WITH matched AS (
  SELECT
    c.id AS complaint_id,
    (
      SELECT w.id
      FROM public.wards w
      WHERE w.is_active = true
        AND w.boundary_coordinates IS NOT NULL
        AND public.betul_point_in_boundary(c.latitude, c.longitude, w.boundary_coordinates)
      ORDER BY w.area_sq_meters ASC NULLS LAST, w.ward_number ASC
      LIMIT 1
    ) AS new_ward_id
  FROM public.complaints c
  WHERE c.latitude IS NOT NULL
    AND c.longitude IS NOT NULL
)
UPDATE public.complaints c
SET ward_id = matched.new_ward_id
FROM matched
WHERE c.id = matched.complaint_id
  AND matched.new_ward_id IS NOT NULL;

WITH canonical_wards AS (
  SELECT DISTINCT ON (ward_number)
    id,
    ward_number
  FROM public.wards
  ORDER BY ward_number ASC, area_sq_meters DESC NULLS LAST, name ASC
)
UPDATE public.complaints c
SET ward_id = cw.id
FROM tmp_complaint_ward t
JOIN canonical_wards cw
  ON cw.ward_number = t.ward_number
WHERE c.id = t.complaint_id
  AND c.ward_id IS NULL
  AND t.ward_number IS NOT NULL;

COMMIT;

NOTIFY pgrst, 'reload schema';

-- 9. Verification summary
SELECT
  COUNT(*) AS total_rows,
  COUNT(DISTINCT ward_number) AS distinct_wards,
  COUNT(*) FILTER (WHERE boundary_coordinates IS NOT NULL) AS polygon_rows,
  COUNT(*) FILTER (WHERE boundary_coordinates IS NULL AND center_latitude IS NULL AND center_longitude IS NULL) AS pending_zero_circle_rows,
  ROUND(COALESCE(SUM(area_sq_meters), 0)::numeric / 10000.0, 2) AS total_mapped_hectares,
  (SELECT COUNT(*) FROM public.complaints WHERE ward_id IS NOT NULL) AS complaints_linked_to_wards
FROM public.wards
WHERE is_active = true;
